import { getUsers } from '@/actions/users';
import { getDisputes } from '@/actions/test-helpers';
import { TestControls } from './test-controls';
import { createAdminClient } from '@/lib/supabase/admin';

export default async function TestMutationsPage() {
    const users = await getUsers(1, 10);
    const disputes = await getDisputes();
    
    // Admin ID: In a real app we get it from auth. 
    // For test page, we can assume a hardcoded admin ID or fetch the first user as "admin".
    // Or we can just use a dummy UUID if the audit log accepts it (it refers to profiles, so must be valid).
    // Let's use the first user's ID as the "Admin" for this test.
    const adminId = users.data[0]?.id || '00000000-0000-0000-0000-000000000000';

    // We need to fetch 'status' and 'metadata' for users because getUsers DTO only has a simplified status.
    // Let's re-fetch raw profiles here for better visibility in test.
    const supabase = await createAdminClient();
    const { data: rawProfiles } = await supabase.from('profiles').select('*').limit(10);
    
    return (
        <div className="p-10 max-w-4xl mx-auto font-sans">
            <h1 className="text-2xl font-bold mb-6">Mutation Verification</h1>
            <p className="mb-4 text-gray-600">
                Acting as Admin ID: <code className="bg-gray-100 p-1 rounded">{adminId}</code>
            </p>
            
            <TestControls 
                users={rawProfiles || []} 
                disputes={disputes} 
                adminId={adminId} 
            />
        </div>
    );
}
